import pandas as pd


def per_weekday(logs):
    days = pd.to_datetime(logs["timestamp"]).dt.dayofweek
    n = days.value_counts().reindex(range(7), fill_value=0)
    return pd.DataFrame({"weekday": range(7), "n": n.to_numpy()})

